# New idea: Replace 0s based on distance to nearest 3
# Cells far from any 3 might stay 0, cells close to 3 might become 9

import heapq

def min_distance_to_3(g):
    h, w = len(g), len(g[0])
    dist = [[float('inf')] * w for _ in range(h)]
    pq = []

    # Add all 3 positions to priority queue with distance 0
    for r in range(h):
        for c in range(w):
            if g[r][c] == 3:
                dist[r][c] = 0
                heapq.heappush(pq, (0, r, c))

    # Dijkstra-like BFS
    while pq:
        d, r, c = heapq.heappop(pq)
        if d > dist[r][c]:
            continue
        for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
            nr, nc = r + dr, c + dc
            if 0 <= nr < h and 0 <= nc < w and dist[nr][nc] > d + 1:
                dist[nr][nc] = d + 1
                heapq.heappush(pq, (d + 1, nr, nc))

    return dist

