from collections import deque

def compute_bfs_distances(g):
    h, w = len(g), len(g[0])
    positions_3 = [(r,c) for r in range(h) for c in range(w) if g[r][c] == 3]
    dist = [[float('inf')] * w for _ in range(h)]
    for sr, sc in positions_3:
        dist[sr][sc] = 0
    q = deque([(sr, sc) for sr, sc in positions_3])
    while q:
        r, c = q.popleft()
        for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
            nr, nc = r + dr, c + dc
            if 0 <= nr < h and 0 <= nc < w and dist[nr][nc] == float('inf'):
                dist[nr][nc] = dist[r][c] + 1
                q.append((nr, nc))
    return dist

dist_map = compute_bfs_distances(grid)

